 "content": "from collections import Counter, deque


def transform(grid):
    """Keep large solid-color rectangles; erase all other speckles."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    # Identify large dense monochrome rectangular objects by their bounding
    # boxes, which tolerate a few foreign-color noise pixels inside the object.
    candidates = []
    for color in range(10):
        if color == bg:
            continue
        seen = [[False] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if seen[r][c] or grid[r][c] != color:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                            seen[yy][xx] = True
                            q.append((yy, xx))
                r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
                c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
                area = (r1-r0+1) * (c1-c0+1)
                # Require a substantial object; later cluster merging covers
                # rectangles split by one or two speckle pixels.
                if area >= 4 and len(cells) / area >= 0.65:
                    candidates.append((len(cells), color, r0, c0, r1, c1))
    # Paint only coherent large objects. Small isolated colored artifacts are
    # removed, while pieces of objects with corruptions are still retained.
    for count, color, r0, c0, r1, c1 in candidates:
        area = (r1-r0+1) * (c1-c0+1)
        if count < 4 or area < 4:
            continue
        for y in range(r0, r1+1):
            for x in range(c0, c1+1):
                out[y][x] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
